import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { reservaService, ReservaResponse } from '../../services/api';
import { quartoService, QuartoResponse } from '../../services/api';
import { clienteService, ClienteResponse } from '../../services/api';
import { pagamentoService } from '../../services/api';
import { formatarDataBrasil } from '../../utils/dateUtils';
import ErrorModal from '../common/ErrorModal';

interface DashboardStats {
  totalReservas: number;
  reservasAtivas: number;
  reservasFinalizadas: number;
  reservasCanceladas: number;
  totalQuartos: number;
  quartosDisponiveis: number;
  quartosOcupados: number;
  quartosManutencao: number;
  totalClientes: number;
  totalReceita: number;
  ocupacaoAtual: number;
}

interface RelatorioMensal {
  mes: string;
  reservas: number;
  receita: number;
  ocupacao: number;
}

const DashboardAdminModern: React.FC = () => {
  const navigate = useNavigate();

  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [relatorioMensal, setRelatorioMensal] = useState<RelatorioMensal[]>([]);
  const [reservasRecentes, setReservasRecentes] = useState<ReservaResponse[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [periodoRelatorio, setPeriodoRelatorio] = useState('6');
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    carregarDadosDashboard();
  }, [periodoRelatorio]);

  const carregarDadosDashboard = async () => {
    setIsLoading(true);
    try {
      console.log('🔄 Iniciando carregamento do Dashboard Admin Moderno...');

      let reservasData: any[] = [];
      let quartosData: any[] = [];
      let clientesData: any[] = [];
      let pagamentosData: any[] = [];

      try {
        reservasData = await reservaService.listarReservas();
        console.log('✅ Reservas carregadas:', reservasData.length);
      } catch (error) {
        console.error('❌ Erro ao carregar reservas:', error);
      }

      try {
        quartosData = await quartoService.listarQuartos();
        console.log('✅ Quartos carregados:', quartosData.length);
      } catch (error) {
        console.error('❌ Erro ao carregar quartos:', error);
      }

      try {
        clientesData = await clienteService.listarClientes();
        console.log('✅ Clientes carregados:', clientesData.length);
      } catch (error) {
        console.error('❌ Erro ao carregar clientes:', error);
      }

      try {
        pagamentosData = await pagamentoService.listarPagamentos();
        console.log('✅ Pagamentos carregados:', pagamentosData.length);
      } catch (error) {
        console.error('❌ Erro ao carregar pagamentos:', error);
        pagamentosData = [];
      }

      const totalReservas = reservasData.length || 0;
      const reservasAtivas = reservasData.filter((r: any) => r.status === 'ATIVA').length || 0;
      const reservasFinalizadas = reservasData.filter((r: any) => r.status === 'FINALIZADA').length || 0;
      const reservasCanceladas = reservasData.filter((r: any) => r.status === 'CANCELADA').length || 0;

      const totalQuartos = quartosData.length || 0;
      const quartosDisponiveis = quartosData.filter((q: any) => q.status === 'DISPONIVEL').length || 0;
      const quartosOcupados = quartosData.filter((q: any) => q.status === 'OCUPADO').length || 0;
      const quartosManutencao = quartosData.filter((q: any) => q.status === 'MANUTENCAO').length || 0;

      const totalClientes = clientesData.length || 0;

      const totalReceita = pagamentosData.reduce((acc: number, pgto: any) => {
        const valor = pgto.valor || pgto.valorTotal || 0;
        return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
      }, 0);

      const ocupacaoAtual = totalQuartos > 0 ? (quartosOcupados / totalQuartos) * 100 : 0;

      const statsData = {
        totalReservas,
        reservasAtivas,
        reservasFinalizadas,
        reservasCanceladas,
        totalQuartos,
        quartosDisponiveis,
        quartosOcupados,
        quartosManutencao,
        totalClientes,
        totalReceita,
        ocupacaoAtual
      };

      console.log('📊 Estatísticas calculadas:', statsData);
      setStats(statsData);

      gerarRelatorioMensal(reservasData, pagamentosData, quartosData);

      const recentes = reservasData
        .sort((a: any, b: any) => new Date(b.createdAt || b.checkIn).getTime() - new Date(a.createdAt || a.checkIn).getTime())
        .slice(0, 10);
      setReservasRecentes(recentes);

    } catch (error) {
      console.error('❌ Erro geral no carregamento do dashboard:', error);
      setErrorMessage('Não foi possível carregar os dados do dashboard. Tente novamente.');
      setShowError(true);

      setStats({
        totalReservas: 0,
        reservasAtivas: 0,
        reservasFinalizadas: 0,
        reservasCanceladas: 0,
        totalQuartos: 0,
        quartosDisponiveis: 0,
        quartosOcupados: 0,
        quartosManutencao: 0,
        totalClientes: 0,
        totalReceita: 0,
        ocupacaoAtual: 0
      });
    } finally {
      setIsLoading(false);
    }
  };

  const gerarRelatorioMensal = (reservas: any[], pagamentos: any[], quartos: any[]) => {
    try {
      console.log('📈 Gerando relatório mensal...');
      const meses = [];
      const hoje = new Date();

      for (let i = parseInt(periodoRelatorio) - 1; i >= 0; i--) {
        const data = new Date(hoje.getFullYear(), hoje.getMonth() - i, 1);
        const mesNome = data.toLocaleDateString('pt-BR', { month: 'short', year: 'numeric' });

        const reservasMes = reservas.filter((r: any) => {
          try {
            const dataReserva = new Date(r.createdAt || r.checkIn);
            return dataReserva.getMonth() === data.getMonth() && 
                   dataReserva.getFullYear() === data.getFullYear();
          } catch (error) {
            return false;
          }
        });

        const receitaMes = pagamentos
          .filter((pgto: any) => {
            try {
              const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt);
              return dataPgto.getMonth() === data.getMonth() && 
                     dataPgto.getFullYear() === data.getFullYear();
            } catch (error) {
              return false;
            }
          })
          .reduce((acc: number, pgto: any) => {
            const valor = pgto.valor || pgto.valorTotal || 0;
            return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
          }, 0);

        const diasNoMes = new Date(data.getFullYear(), data.getMonth() + 1, 0).getDate();
        const ocupacaoDiaria = [];

        for (let dia = 1; dia <= diasNoMes; dia++) {
          const dataDia = new Date(data.getFullYear(), data.getMonth(), dia);
          const quartosOcupadosDia = reservas.filter((r: any) => {
            try {
              const checkIn = new Date(r.checkIn);
              const checkOut = new Date(r.checkOut);
              return dataDia >= checkIn && dataDia < checkOut && r.status === 'ATIVA';
            } catch (error) {
              return false;
            }
          }).length;

          ocupacaoDiaria.push(quartosOcupadosDia);
        }

        const ocupacaoMedia = quartos.length > 0 
          ? (ocupacaoDiaria.reduce((acc, val) => acc + val, 0) / (diasNoMes * quartos.length)) * 100 
          : 0;

        meses.push({
          mes: mesNome,
          reservas: reservasMes.length,
          receita: receitaMes,
          ocupacao: Math.round(ocupacaoMedia * 10) / 10
        });
      }

      console.log('📊 Relatório mensal gerado:', meses);
      setRelatorioMensal(meses);
    } catch (error) {
      console.error('❌ Erro ao gerar relatório mensal:', error);
      setRelatorioMensal([]);
    }
  };

  const formatarMoeda = (valor: number) => {
    return valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ATIVA':
        return 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200';
      case 'FINALIZADA':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200';
      case 'CANCELADA':
        return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200';
      case 'RESERVADA':
        return 'bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200';
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800 flex items-center justify-center">
        <div className="text-center">
          <div className="relative">
            <div className="animate-spin rounded-full h-16 w-16 border-4 border-slate-200 dark:border-slate-700 border-t-blue-600"></div>
            <div className="absolute inset-0 rounded-full h-16 w-16 border-4 border-transparent border-t-blue-400 animate-pulse"></div>
          </div>
          <p className="mt-6 text-lg font-medium text-slate-600 dark:text-slate-400">Carregando dashboard...</p>
        </div>
      </div>
    );
  }

  if (!stats) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800 flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">📊</div>
          <p className="text-lg text-slate-600 dark:text-slate-400">Não foi possível carregar os dados.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl font-bold text-slate-900 dark:text-white">Dashboard Administrativo</h1>
              <p className="mt-2 text-slate-600 dark:text-slate-400">Visão geral e métricas do sistema</p>
            </div>
            <div className="flex items-center space-x-4">
              <select
                value={periodoRelatorio}
                onChange={(e) => setPeriodoRelatorio(e.target.value)}
                className="px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="3">Últimos 3 meses</option>
                <option value="6">Últimos 6 meses</option>
                <option value="12">Últimos 12 meses</option>
              </select>
            </div>
          </div>
        </div>

        {/* Cards de Estatísticas - Grid Moderno */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg p-6 border border-slate-200 dark:border-slate-700 hover:shadow-xl transition-shadow duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl flex items-center justify-center">
                <span className="text-white text-xl">📊</span>
              </div>
              <span className="text-sm font-medium text-blue-600 dark:text-blue-400">+12%</span>
            </div>
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white">{stats.totalReservas}</h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">Total Reservas</p>
          </div>

          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg p-6 border border-slate-200 dark:border-slate-700 hover:shadow-xl transition-shadow duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 bg-gradient-to-br from-emerald-500 to-emerald-600 rounded-xl flex items-center justify-center">
                <span className="text-white text-xl">🏨</span>
              </div>
              <span className="text-sm font-medium text-emerald-600 dark:text-emerald-400">+8%</span>
            </div>
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white">{stats.ocupacaoAtual.toFixed(1)}%</h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">Taxa Ocupação</p>
          </div>

          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg p-6 border border-slate-200 dark:border-slate-700 hover:shadow-xl transition-shadow duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 bg-gradient-to-br from-amber-500 to-amber-600 rounded-xl flex items-center justify-center">
                <span className="text-white text-xl">💰</span>
              </div>
              <span className="text-sm font-medium text-amber-600 dark:text-amber-400">+23%</span>
            </div>
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white">{formatarMoeda(stats.totalReceita)}</h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">Receita Total</p>
          </div>

          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg p-6 border border-slate-200 dark:border-slate-700 hover:shadow-xl transition-shadow duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-purple-600 rounded-xl flex items-center justify-center">
                <span className="text-white text-xl">👥</span>
              </div>
              <span className="text-sm font-medium text-purple-600 dark:text-purple-400">+15%</span>
            </div>
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white">{stats.totalClientes}</h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">Total Clientes</p>
          </div>
        </div>

        {/* Gráfico de Relatório Mensal */}
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg p-6 border border-slate-200 dark:border-slate-700 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold text-slate-900 dark:text-white">Relatório Mensal</h2>
            <div className="flex items-center space-x-6 text-sm">
              <div className="flex items-center">
                <div className="w-3 h-3 bg-blue-500 rounded-full mr-2"></div>
                <span className="text-slate-600 dark:text-slate-400">Reservas</span>
              </div>
              <div className="flex items-center">
                <div className="w-3 h-3 bg-emerald-500 rounded-full mr-2"></div>
                <span className="text-slate-600 dark:text-slate-400">Receita</span>
              </div>
              <div className="flex items-center">
                <div className="w-3 h-3 bg-amber-500 rounded-full mr-2"></div>
                <span className="text-slate-600 dark:text-slate-400">Ocupação</span>
              </div>
            </div>
          </div>

          <div className="space-y-4">
            {relatorioMensal.map((mes, index) => (
              <div key={index} className="flex items-center space-x-4">
                <div className="w-24 text-sm font-medium text-slate-700 dark:text-slate-300">
                  {mes.mes}
                </div>
                <div className="flex-1">
                  <div className="flex items-center space-x-2">
                    <div className="flex-1 bg-slate-100 dark:bg-slate-700 rounded-full h-6 relative overflow-hidden">
                      <div 
                        className="absolute top-0 left-0 h-full bg-gradient-to-r from-blue-500 to-blue-600 rounded-full transition-all duration-500"
                        style={{ width: `${Math.min((mes.reservas / Math.max(...relatorioMensal.map(r => r.reservas))) * 100, 100)}%` }}
                      ></div>
                    </div>
                    <span className="text-xs font-medium text-slate-600 dark:text-slate-400 w-12 text-right">
                      {mes.reservas}
                    </span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className="flex-1 bg-slate-100 dark:bg-slate-700 rounded-full h-6 relative overflow-hidden">
                      <div 
                        className="absolute top-0 left-0 h-full bg-gradient-to-r from-emerald-500 to-emerald-600 rounded-full transition-all duration-500"
                        style={{ width: `${Math.min((mes.receita / Math.max(...relatorioMensal.map(r => r.receita))) * 100, 100)}%` }}
                      ></div>
                    </div>
                    <span className="text-xs font-medium text-slate-600 dark:text-slate-400 w-20 text-right">
                      {formatarMoeda(mes.receita)}
                    </span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className="flex-1 bg-slate-100 dark:bg-slate-700 rounded-full h-6 relative overflow-hidden">
                      <div 
                        className="absolute top-0 left-0 h-full bg-gradient-to-r from-amber-500 to-amber-600 rounded-full transition-all duration-500"
                        style={{ width: `${mes.ocupacao}%` }}
                      ></div>
                    </div>
                    <span className="text-xs font-medium text-slate-600 dark:text-slate-400 w-12 text-right">
                      {mes.ocupacao}%
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Reservas Recentes */}
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700">
          <div className="p-6 border-b border-slate-200 dark:border-slate-700">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white">Reservas Recentes</h2>
              <button
                onClick={() => navigate('/user/consultar-reservas')}
                className="text-blue-600 hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300 text-sm font-medium"
              >
                Ver todas →
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 dark:bg-slate-900">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">ID</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">Cliente</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">Quarto</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">Período</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
                {reservasRecentes.map((reserva) => (
                  <tr key={reserva.id} className="hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-900 dark:text-white">
                      #{reserva.id}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-700 dark:text-slate-300">
                      {reserva.clienteNome}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-700 dark:text-slate-300">
                      {reserva.quartoNumero}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-700 dark:text-slate-300">
                      {formatarDataBrasil(reserva.checkIn)} - {formatarDataBrasil(reserva.checkOut)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(reserva.status)}`}>
                        {reserva.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Modal de Erro */}
        {showError && (
          <ErrorModal
            isOpen={showError}
            title="Erro"
            message={errorMessage}
            onClose={() => setShowError(false)}
          />
        )}
      </div>
    </div>
  );
};

export default DashboardAdminModern;
